from pathlib import Path


def replace_block(text: str, start: str, end: str, replacement: str) -> str:
    i = text.index(start)
    j = text.index(end, i)
    return text[:i] + replacement + text[j:]

# --- cooperative sleep scene becomes sleep -> morning wake scene ---
p = Path('scripts/coop_session.gd')
s = p.read_text()
s = s.replace('const PROTOCOL := "slapdash-cafe-rest-20"', 'const PROTOCOL := "slapdash-cafe-wake-21"')
s = s.replace('const SLEEP_SECONDS := 7.0\n', 'const SLEEP_SECONDS := 7.0\nconst WAKE_SECONDS := 5.8\n')
s = s.replace('''func sleep_scene_age() -> float:\n\treturn float(sleep_scene.get("age",0.0))\n\n''', '''func sleep_scene_age() -> float:\n\treturn float(sleep_scene.get("age",0.0))\n\nfunc sleep_scene_phase() -> String:\n\treturn str(sleep_scene.get("phase","sleep"))\n\n''')
s = s.replace('''\tvar previous_age:=sleep_scene_age()\n\tvar same_scene: bool=sleep_scene.get("serial",-1)==scene.get("serial",-2)\n\tsleep_scene=scene.duplicate(true)\n\tif same_scene and sleep_scene_active(): sleep_scene.age=maxf(previous_age,sleep_scene_age())\n''', '''\tvar previous_age:=sleep_scene_age()\n\tvar same_scene: bool=sleep_scene.get("serial",-1)==scene.get("serial",-2)\n\tvar same_phase: bool=sleep_scene_phase()==str(scene.get("phase","sleep"))\n\tsleep_scene=scene.duplicate(true)\n\tif same_scene and same_phase and sleep_scene_active(): sleep_scene.age=maxf(previous_age,sleep_scene_age())\n''')
new_sleep = '''func _try_finish_sleep() -> bool:\n\tif guest or sleep_scene_active() or game.service.progress.shift!="night": return false\n\tif game.service.any_training(): return false\n\tif str(game.laboratory.state.get("phase","idle")) not in ["idle","done"]: return false\n\tvar participants:=sleep_participants()\n\tif participants.is_empty(): return false\n\tfor id in participants:\n\t\tif not sleeping_peers.has(id): return false\n\tsleep_scene={"active":true,"phase":"sleep","age":0.0,"serial":sleep_revision+1,"participants":participants,"skips":[],"night_start":game.service.progress.night_elapsed}\n\t_broadcast_sleep_state()\n\treturn true\n\nfunc _scene_unanimous() -> bool:\n\tvar participants: Array=sleep_scene.get("participants",[])\n\tvar skips: Array=sleep_scene.get("skips",[])\n\tif participants.is_empty(): return false\n\tfor id in participants:\n\t\tif id not in skips: return false\n\treturn true\n\nfunc _advance_sleep(delta: float) -> void:\n\tif not sleep_scene_active(): return\n\tvar phase:=sleep_scene_phase()\n\tvar duration: float=SLEEP_SECONDS if phase=="sleep" else WAKE_SECONDS\n\tsleep_scene.age=minf(duration,sleep_scene_age()+delta)\n\tif guest: return\n\tif phase=="sleep" and game.service.progress.shift!="night":\n\t\tclear_sleeping(); _broadcast_sleep_state(); return\n\tif phase=="wake" and game.service.progress.shift!="open":\n\t\tclear_sleeping(); _broadcast_sleep_state(); return\n\tif sleep_scene_age()<duration and not _scene_unanimous(): return\n\tif phase=="sleep":\n\t\tvar error: String=game.service.next_day()\n\t\tif not error.is_empty():\n\t\t\tclear_sleeping()\n\t\t\t_broadcast_sleep_state()\n\t\t\tgame.service.announce(error)\n\t\t\treturn\n\t\tsleep_scene.phase="wake"\n\t\tsleep_scene.age=0.0\n\t\tsleep_scene.skips=[]\n\t\tsleep_scene.morning_day=game.service.progress.day\n\t\t_broadcast_sleep_state()\n\t\tgame.save_cafe()\n\t\treturn\n\tclear_sleeping()\n\t_broadcast_sleep_state()\n\tvar bonus:=roundi((game.service.progress.rest_multiplier-1.0)*100)\n\tgame.service.announce("День %d · кафе открыто · отдых: +%d%% к темпу клонов."%[game.service.progress.day,bonus])\n\tgame.save_cafe()\n\n'''
s = replace_block(s, 'func _try_finish_sleep() -> bool:\n', 'func _sleep_action(sender: int, value: Dictionary) -> String:\n', new_sleep)
s = s.replace('if not guest and game.service.progress.shift != "night" and not sleeping_peers.is_empty():', 'if not guest and game.service.progress.shift != "night" and not sleep_scene_active() and not sleeping_peers.is_empty():')
s = s.replace('''\t\tif sleeping_peers.has(id):\n\t\t\tgame.annex.settle_player_avatar(avatar,int(sleeping_peers[id]))\n\t\t\tavatar.caption.text += "\\nСпит"\n''', '''\t\tif sleeping_peers.has(id):\n\t\t\tvar layer:=int(sleeping_peers[id])\n\t\t\tif sleep_scene_active() and sleep_scene_phase()=="wake":\n\t\t\t\tvar rise:=smoothstep(0.0,1.0,clampf(sleep_scene_age()/1.15,0.0,1.0))\n\t\t\t\tavatar.morning_wake_pose(game.annex.player_bed_exit(layer,game.service.progress.lounge_tier),0.0,rise,int(id))\n\t\t\t\tavatar.caption.text += "\\nПросыпается"\n\t\t\telse:\n\t\t\t\tgame.annex.settle_player_avatar(avatar,layer)\n\t\t\t\tavatar.caption.text += "\\nСпит"\n''')
p.write_text(s)

# --- cinematic camera/fade for morning ---
p = Path('scripts/sleep_cinematic.gd')
s = p.read_text()
new_process = '''func _process(_delta: float) -> void:\n\tif game==null: return\n\tvar active: bool=game.session.sleep_scene_active()\n\tif active and not showing: begin()\n\tif not active:\n\t\tif showing: finish()\n\t\treturn\n\tvar age: float=game.session.sleep_scene_age()\n\tvar scene: Dictionary=game.session.sleep_scene\n\tvar phase: String=game.session.sleep_scene_phase()\n\tvar forecast:=Rest.report(game.service.progress,game.evening.workers().size())\n\tvar back:=Layout.back_z(game.service.progress.lounge_tier)\n\tif phase=="sleep":\n\t\ttitle.text="СМЕНА ЗАКОНЧЕНА" if age<2.1 else "ТИХИЙ ЧАС ДЛЯ ОЧЕНЬ УСТАВШИХ"\n\t\thint.text="Завтра: +%d%% к темпу команды\\nПробел · пропустить вместе (%d/%d)"%[roundi(float(forecast.bonus)*100),scene.skips.size(),scene.participants.size()]\n\t\tshade.color=Color(0,0,0,maxf(clampf(1.0-age/0.4,0,1),clampf((age-6.45)/0.55,0,1)))\n\t\tif is_instance_valid(self_avatar):\n\t\t\tself_avatar.visible=game.session.local_sleeping()\n\t\t\tif self_avatar.visible:\n\t\t\t\tgame.annex.settle_player_avatar(self_avatar,game.session.local_sleep_bed())\n\t\t\t\tself_avatar.caption.hide()\n\t\treturn\n\n\t# The black frame at the end of the sleep shot becomes the first frame of morning.\n\ttitle.text="ДОБРОЕ УТРО · ДЕНЬ %d"%int(scene.get("morning_day",game.service.progress.day))\n\thint.text="Клоны уже бегут на рабочие места\\nПробел · пропустить вместе (%d/%d)"%[scene.skips.size(),scene.participants.size()]\n\tshade.color=Color(0,0,0,clampf(1.0-age/0.65,0,1))\n\tvar daylight_blend:=smoothstep(0.0,1.0,clampf(age/1.45,0,1))\n\tgame.daylight.light_energy=lerpf(0.12,0.75,daylight_blend)\n\tgame.room_environment.environment.ambient_light_energy=lerpf(0.26,0.35,daylight_blend)\n\tvar travel:=smoothstep(0.0,1.0,clampf((age-0.55)/4.3,0,1))\n\tvar camera_start:=Vector3(15.7,4.15,back-1.0)\n\tvar camera_end:=Vector3(12.0,3.15,8.15)\n\tvar look_start:=Vector3(10.4,1.0,maxf(13.4,back-4.0))\n\tvar look_end:=Vector3(3.0,1.05,-1.4)\n\tshot.global_position=camera_start.lerp(camera_end,travel)\n\tshot.look_at(look_start.lerp(look_end,travel),Vector3.UP)\n\tif is_instance_valid(self_avatar):\n\t\tself_avatar.visible=game.session.local_sleeping()\n\t\tif self_avatar.visible:\n\t\t\tvar layer:=game.session.local_sleep_bed()\n\t\t\tvar rise:=smoothstep(0.0,1.0,clampf(age/1.15,0,1))\n\t\t\tself_avatar.morning_wake_pose(game.annex.player_bed_exit(layer,game.service.progress.lounge_tier),0.0,rise,game.session.local_id())\n\t\t\tself_avatar.caption.hide()\n'''
s = replace_block(s, 'func _process(_delta: float) -> void:\n', '\n', new_process) if False else s
# _process is the final function in this file.
i = s.index('func _process(_delta: float) -> void:\n')
s = s[:i] + new_process
p.write_text(s)

# --- avatar: social lounge gestures, wake-up and varied morning runs ---
p = Path('scripts/cook_avatar.gd')
s = p.read_text()
s = s.replace('var seated: bool=pose in ["watch","rock","tea","board","relax","floor"]', 'var seated: bool=pose in ["watch","chat","rock","tea","board","relax","floor"]')
s = s.replace('''\t\t"watch":\n\t\t\thead.rotation.y=sin(clock*0.25+identity)*0.09\n''', '''\t\t"watch":\n\t\t\thead.rotation.y=sin(clock*0.25+identity)*0.09\n\t\t"chat":\n\t\t\tvar talk:=fposmod(clock+identity*1.37,6.4)\n\t\t\tvar side: float=-1.0 if str(spot.id)=="sofa_right" else 1.0 if str(spot.id)=="sofa_left" else sin(clock*0.43+identity)\n\t\t\thead.rotation.y=side*(0.52+sin(clock*0.8+identity)*0.16)\n\t\t\thead.rotation.x=sin(clock*2.4+identity)*0.06\n\t\t\tif talk<2.35:\n\t\t\t\tvar gesture:=sin(talk/2.35*PI)\n\t\t\t\tright=right.lerp(Vector3(0.52,1.18,-0.28),gesture)\n\t\t\t\tleft=left.lerp(Vector3(-0.40,1.04,-0.33),gesture*0.55)\n\t\t\telif talk>4.35 and talk<5.45:\n\t\t\t\tvar laugh:=sin((talk-4.35)/1.10*PI)\n\t\t\t\trotation.z=sin(clock*8.0+identity)*0.035*laugh\n\t\t\t\thead.rotation.x=-0.12*clampf(laugh,0,1)\n\t\t\t\tleft.y-=0.08*clampf(laugh,0,1)\n\t\t\t\tright.y-=0.08*clampf(laugh,0,1)\n''')
s = s.replace('''\t\t"floor":\n\t\t\tposition.y-=0.50\n\t\t\thead.rotation.x=-0.08\n''', '''\t\t"floor":\n\t\t\tposition.y-=0.50\n\t\t\tvar floor_beat:=fposmod(clock*0.78+identity*1.11,7.0)\n\t\t\thead.rotation.x=-0.08+sin(clock*1.7+identity)*0.05\n\t\t\thead.rotation.y=sin(clock*0.62+identity)*0.48\n\t\t\tif floor_beat<2.2:\n\t\t\t\tvar story:=sin(floor_beat/2.2*PI)\n\t\t\t\tright=right.lerp(Vector3(0.50,1.03,-0.28),story)\n\t\t\telif floor_beat>4.6 and floor_beat<5.8:\n\t\t\t\tvar laugh:=sin((floor_beat-4.6)/1.2*PI)\n\t\t\t\trotation.z=sin(clock*9.0+identity)*0.045*laugh\n\t\t\t\tleft.y-=0.10*laugh\n\t\t\t\tright.y-=0.10*laugh\n''')
insert = '''\nfunc lounge_ball_react(target: Vector3, pass_phase: float, throwing: bool) -> void:\n\tvar local_target:=to_local(target)\n\thead.rotation.y=clampf(atan2(-local_target.x,-local_target.z),-1.0,1.0)\n\thead.rotation.x=clampf(-atan2(local_target.y-1.45,maxf(0.2,Vector2(local_target.x,local_target.z).length())),-0.35,0.35)\n\tvar reach:=sin(clampf(pass_phase,0.0,1.0)*PI)\n\tvar right:=Vector3(0.30,0.82,-0.43)\n\tvar left:=Vector3(-0.30,0.82,-0.43)\n\tif throwing:\n\t\tright=right.lerp(Vector3(0.48,1.34,-0.30),clampf(1.2-pass_phase,0.0,1.0))\n\telse:\n\t\tvar catch:=smoothstep(0.55,1.0,pass_phase)\n\t\tright=right.lerp(Vector3(0.20,1.24,-0.38),catch)\n\t\tleft=left.lerp(Vector3(-0.20,1.24,-0.38),catch)\n\tP.align_line(arms[0],Vector3(-0.3,1.2,0),left)\n\tP.align_line(arms[1],Vector3(0.3,1.2,0),right+Vector3(0,reach*0.04,0))\n\nfunc morning_wake_pose(at: Vector3, yaw: float, rise: float, identity: int) -> void:\n\treset_lounge_accessories()\n\that.hide(); notebook.hide(); book.set_reading(false)\n\tvar eased:=smoothstep(0.0,1.0,clampf(rise,0.0,1.0))\n\tposition=at-Vector3.UP*(1.0-eased)*0.28\n\trotation=Vector3(0,yaw,0)\n\thead.rotation=Vector3(-0.34*(1.0-eased)+sin(identity*1.7+eased*PI)*0.06,0,0)\n\tfor i in range(legs.size()): legs[i].rotation.x=(1.0-eased)*(0.75 if i==0 else -0.55)\n\tfor i in range(arms.size()):\n\t\tvar side: float=-1.0 if i==0 else 1.0\n\t\tvar sleepy:=Vector3(side*0.33,0.84,-0.18)\n\t\tvar stretch:=Vector3(side*0.48,1.92,-0.04)\n\t\tvar hand:=stretch.lerp(sleepy,eased)\n\t\tP.align_line(arms[i],Vector3(side*0.3,1.2,0),hand)\n\nfunc morning_run(clock: float, variant: int) -> void:\n\treset_lounge_accessories()\n\that.hide(); notebook.hide(); book.set_reading(false)\n\tvar kind:=posmod(variant,5)\n\tvar beat:=clock*[11.0,9.0,14.0,10.5,12.0][kind]\n\tvar bounce: float=[0.08,0.20,0.045,0.11,0.14][kind]\n\tposition.y+=absf(sin(beat))*bounce\n\trotation.x=-0.10 if kind==2 else 0.0\n\trotation.z=sin(beat*0.5)*0.07 if kind in [1,4] else 0.0\n\tfor i in range(legs.size()): legs[i].rotation.x=sin(beat+i*PI)*([0.62,0.82,0.95,0.70,0.78][kind])\n\thead.rotation=Vector3(-0.06,sin(beat*0.22+kind)*0.17,0)\n\tfor i in range(arms.size()):\n\t\tvar side: float=-1.0 if i==0 else 1.0\n\t\tvar hand:=Vector3(side*0.38,0.90,-0.12+sin(beat+i*PI)*0.28)\n\t\tif kind==1 and i==1: hand=Vector3(0.62,1.72,-0.05+sin(beat)*0.12)\n\t\telif kind==3: hand=Vector3(side*0.72,1.30,-0.12+sin(beat+i)*0.08)\n\t\telif kind==4 and i==0: hand=Vector3(-0.54,1.55,-0.10)\n\t\tP.align_line(arms[i],Vector3(side*0.3,1.2,0),hand)\n\n'''
s = s.replace('\nfunc reset_lounge_accessories() -> void:\n', insert + 'func reset_lounge_accessories() -> void:\n')
p.write_text(s)

# --- lounge: sofa conversation and floor circles ---
p = Path('scripts/lounge_layout.gd')
s = p.read_text()
s = s.replace('slot("sofa_left","sofa",Vector3(5.62,-0.10,14.45),Vector3(5.62,0,13.65),0,"watch","Смотрит телевизор")', 'slot("sofa_left","sofa",Vector3(5.62,-0.10,14.45),Vector3(5.62,0,13.65),0,"chat","Болтает на диване")')
s = s.replace('slot("sofa_middle","sofa",Vector3(6.5,-0.10,14.45),Vector3(6.5,0,13.65),0,"watch","Смотрит телевизор")', 'slot("sofa_middle","sofa",Vector3(6.5,-0.10,14.45),Vector3(6.5,0,13.65),0,"chat","Рассказывает историю")')
s = s.replace('slot("sofa_right","sofa",Vector3(7.38,-0.10,14.45),Vector3(7.38,0,13.65),0,"watch","Смотрит телевизор")', 'slot("sofa_right","sofa",Vector3(7.38,-0.10,14.45),Vector3(7.38,0,13.65),0,"chat","Смеётся с соседями")')
new_overflow = '''static func overflow_slot(index: int, tier := 2, owned: Array = []) -> Dictionary:\n\tvar blockers:=obstacles(tier,owned)\n\tvar ring: Array=[]\n\tfor center_z in [14.0,16.6,19.2,21.8,24.3]:\n\t\tif center_z>back_z(tier)-1.25: continue\n\t\tvar center:=Vector3(AISLE_X,0,center_z)\n\t\tfor spoke in range(6):\n\t\t\tvar angle:=TAU*float(spoke)/6.0\n\t\t\tvar point:=center+Vector3(cos(angle)*1.08,0,sin(angle)*0.82)\n\t\t\tif walkable(point,blockers,tier): ring.append({"point":point,"center":center})\n\tif not ring.is_empty():\n\t\tvar chosen: Dictionary=ring[index%ring.size()]\n\t\tvar base: Vector3=chosen.point\n\t\tvar layer:=int(index/ring.size())\n\t\tvar point:=base+Vector3(0,layer*0.34,0)\n\t\tvar toward: Vector3=Vector3(chosen.center)-base\n\t\tvar yaw:=atan2(-toward.x,-toward.z)\n\t\tvar activity: String=["Перекидывается мячиком","Болтает на ковре","Смеётся в кружке","Слушает байку"][index%4]\n\t\treturn slot("overflow_%d"%index,"floor",point,base,yaw,"floor",activity)\n\tvar candidates: Array=[]\n\tfor z in range(12,24):\n\t\tfor x in [9.1,11.5,16.4]:\n\t\t\tvar point:=Vector3(x,0,float(z)+0.25)\n\t\t\tif walkable(point,blockers,tier): candidates.append(point)\n\tif candidates.is_empty(): candidates.append(ENTRANCE)\n\tvar base: Vector3=candidates[index%candidates.size()]\n\tvar layer:=int(index/candidates.size())\n\tvar point:=base+Vector3(0,layer*0.34,0)\n\tvar toward:=Vector3(AISLE_X,0,clampf(base.z,12.5,back_z(tier)-1.3))-base\n\tvar yaw:=atan2(-toward.x,-toward.z) if toward.length()>0.05 else float(index%4)*PI/2.0\n\treturn slot("overflow_%d"%index,"floor",point,base,yaw,"floor","Болтает на ковре")\n\n'''
s = replace_block(s, 'static func overflow_slot(index: int, tier := 2, owned: Array = []) -> Dictionary:\n', 'static func rest_spot(index: int, tier := 2, owned: Array = []) -> Dictionary:\n', new_overflow)
p.write_text(s)

# --- evening workers: keep actors through dawn, wake/run home, floor ball ---
p = Path('scripts/staff_evening.gd')
s = p.read_text()
s = s.replace('var cached_plan: Array = []\n', 'var cached_plan: Array = []\nvar lounge_ball: Node3D\n')
s = s.replace('''func setup(owner_game: Node3D) -> void:\n\tgame=owner_game\n''', '''func setup(owner_game: Node3D) -> void:\n\tgame=owner_game\n\tlounge_ball=Props.ball(self,0.105,Vector3.ZERO,Color("e6b45f"))\n\tlounge_ball.hide()\n''')
new_process = '''func _sample_route(route: Array, distance: float) -> Dictionary:\n\tvar point: Vector3=route[0]\n\tvar direction:=Vector3.BACK\n\tvar done:=route.size()<2\n\tfor i in range(1,route.size()):\n\t\tvar segment: Vector3=Vector3(route[i])-Vector3(route[i-1])\n\t\tif distance<=segment.length():\n\t\t\tpoint=Vector3(route[i-1])+segment.normalized()*distance\n\t\t\tdirection=segment\n\t\t\treturn {"position":point,"direction":direction,"done":false}\n\t\tdistance-=segment.length()\n\t\tpoint=Vector3(route[i])\n\t\tdirection=segment\n\t\tif i==route.size()-1: done=true\n\treturn {"position":point,"direction":direction,"done":done}\n\nfunc _animate_floor_ball(clock: float) -> void:\n\tif not is_instance_valid(lounge_ball): return\n\tvar floor_group: Array=[]\n\tfor id in performers:\n\t\tvar entry: Dictionary=performers[id]\n\t\tif entry.get("settled",false) and str(entry.get("item",""))=="floor" and is_instance_valid(entry.actor): floor_group.append({"id":int(id),"actor":entry.actor})\n\tif floor_group.size()<2:\n\t\tlounge_ball.hide()\n\t\treturn\n\tfloor_group.sort_custom(func(a,b): return int(a.id)<int(b.id))\n\tvar duration:=2.25\n\tvar turn:=int(floor(clock/duration))\n\tvar sender: Dictionary=floor_group[turn%floor_group.size()]\n\tvar receiver: Dictionary=floor_group[(turn+1)%floor_group.size()]\n\tvar pass_phase:=fposmod(clock,duration)/duration\n\tvar from: Vector3=sender.actor.head.global_position+Vector3(0,-0.48,0)\n\tvar to: Vector3=receiver.actor.head.global_position+Vector3(0,-0.48,0)\n\tlounge_ball.global_position=from.lerp(to,pass_phase)+Vector3.UP*sin(pass_phase*PI)*0.72\n\tlounge_ball.show()\n\tsender.actor.lounge_ball_react(to,pass_phase,true)\n\treceiver.actor.lounge_ball_react(from,pass_phase,false)\n\nfunc _process(_delta: float) -> void:\n\tif game==null: return\n\tvar cinematic: bool=game.session.sleep_scene_active()\n\tvar wake_scene: bool=cinematic and game.session.sleep_scene_phase()=="wake"\n\tif game.service.progress.shift!="night" and not wake_scene:\n\t\tfor entry in performers.values(): entry.actor.queue_free(); entry.hat.queue_free(); entry.sleepy.queue_free()\n\t\tperformers.clear()\n\t\tplan_stamp=""\n\t\tcached_plan.clear()\n\t\tif is_instance_valid(lounge_ball): lounge_ball.hide()\n\t\treturn\n\tvar assignments: Array=cached_plan if wake_scene and not cached_plan.is_empty() else plan()\n\tvar current_ids: Array=[]\n\tfor index in range(assignments.size()):\n\t\tvar info: Dictionary=assignments[index].worker\n\t\tvar spot: Dictionary=assignments[index].spot\n\t\tvar id:=int(info.id)\n\t\tcurrent_ids.append(id)\n\t\tif not performers.has(id):\n\t\t\tvar actor:=Avatar.new(); add_child(actor)\n\t\t\tactor.add_to_group("automatic_door_actor")\n\t\t\tvar hat:=Node3D.new(); add_child(hat)\n\t\t\tvar sleepy:=Props.text(self,"z Z z",Vector3.ZERO,22,Color("f1d9ae"))\n\t\t\tsleepy.billboard=BaseMaterial3D.BILLBOARD_ENABLED\n\t\t\tsleepy.pixel_size=0.005\n\t\t\tsleepy.hide()\n\t\t\tProps.cylinder(hat,0.26,0.22,Vector3.ZERO,Color("fff0cb"))\n\t\t\tProps.cylinder(hat,0.29,0.04,Vector3(0,-0.09,0),Color("eee0b6"))\n\t\t\tperformers[id]={"actor":actor,"hat":hat,"sleepy":sleepy}\n\t\tvar entry: Dictionary=performers[id]\n\t\tvar actor: Node3D=entry.actor\n\t\tvar hat: Node3D=entry.hat\n\t\tentry.sleepy.hide()\n\t\tvar station=info.station\n\t\tvar training: bool=station!=null and station.training.active()\n\t\tactor.visible=not training\n\n\t\tif wake_scene:\n\t\t\tvar age: float=game.session.sleep_scene_age()\n\t\t\tvar start_delay:=0.20+float(index%10)*0.075\n\t\t\tvar rise_duration:=0.82+float(id%3)*0.08\n\t\t\tvar sleeping_spot:=Lounge.sleep_spot(spot,id,game.service.progress.lounge_tier)\n\t\t\tentry.settled=false\n\t\t\tentry.item=str(spot.item)\n\t\t\tactor.caption.visible=false\n\t\t\tactor.hat.hide()\n\t\t\tif age<start_delay:\n\t\t\t\tactor.sleep_pose(sleeping_spot,age,id)\n\t\t\telif age<start_delay+rise_duration:\n\t\t\t\tvar rise:=smoothstep(0.0,1.0,clampf((age-start_delay)/rise_duration,0,1))\n\t\t\t\tvar from: Vector3=sleeping_spot.position\n\t\t\t\tvar to: Vector3=spot.approach\n\t\t\t\tvar at:=from.lerp(to,rise)+Vector3.UP*sin(rise*PI)*0.16\n\t\t\t\tactor.morning_wake_pose(at,float(spot.get("yaw",0)),rise,id)\n\t\t\telse:\n\t\t\t\tvar run_clock:=age-start_delay-rise_duration\n\t\t\t\tvar reverse_route: Array=assignments[index].route.duplicate()\n\t\t\t\treverse_route.reverse()\n\t\t\t\tvar variant:=id%5\n\t\t\t\tvar speed: float=[4.4,5.15,3.85,4.75,4.15][variant]\n\t\t\t\tvar sample:=_sample_route(reverse_route,run_clock*speed)\n\t\t\t\tactor.position=sample.position\n\t\t\t\tvar direction: Vector3=sample.direction\n\t\t\t\tactor.rotation.y=atan2(-direction.x,-direction.z)\n\t\t\t\tif sample.done:\n\t\t\t\t\tactor.position=info.home\n\t\t\t\t\tactor.rotation.y=station.global_rotation.y if station!=null else 0.0\n\t\t\t\t\tactor.celebrate(run_clock,variant%3,false)\n\t\t\t\telse: actor.morning_run(run_clock,variant)\n\t\t\t\that.visible=not training and not sample.done\n\t\t\tcontinue\n\n\t\tvar clock: float=game.service.progress.night_elapsed\n\t\tif cinematic: clock=maxf(clock,float(game.session.sleep_scene.night_start)+game.session.sleep_scene_age()*9.0)\n\t\tvar t:=maxf(0,clock-index*0.18)\n\t\tvar variant:=id%3\n\t\tvar home: Vector3=info.home\n\t\tvar route: Array=assignments[index].route\n\t\tvar speed: float=[3.6,4.6,2.9][variant]\n\t\tvar sample:=_sample_route(route,maxf(0,t-0.85)*speed)\n\t\tvar point: Vector3=sample.position\n\t\tvar direction: Vector3=sample.direction\n\t\tvar done: bool=sample.done\n\t\tentry.settled=done and not training\n\t\tentry.item=str(spot.item)\n\t\tif done:\n\t\t\tsettle(actor,spot,id)\n\t\t\tactor.caption.text=str(info.name)+"\\n"+str(spot.activity)\n\t\t\tactor.caption.pixel_size=0.0038\n\t\t\tactor.caption.visible=game.camera.global_position.distance_squared_to(actor.global_position)<25.0\n\t\telse:\n\t\t\tactor.position=point\n\t\t\tactor.rotation.y=atan2(-direction.x,-direction.z)\n\t\t\tactor.caption.text=str(info.name)+" · смена закончилась!"\n\t\t\tactor.caption.visible=true\n\t\t\tactor.celebrate(t,variant,t<0.85)\n\t\tactor.hat.visible=not done and t<0.42\n\t\that.visible=t>=0.42 and not training\n\t\tvar ht:=clampf(t-0.42,0,1.25)\n\t\that.position=home+Vector3(sin(id*2.7)*ht*1.6,maxf(0.12,1.8+2.2*ht-3.0*ht*ht),cos(id*2.7)*ht*1.5)\n\t\that.rotation=Vector3(ht*5,ht*3,ht*4)\n\t\tif t>1.67: hat.position.y=0.12\n\t\tif cinematic and done:\n\t\t\tvar age: float=game.session.sleep_scene_age()\n\t\t\tvar blend:=smoothstep(0.0,1.0,clampf((age-2.1-float(index%10)*0.09)/1.3,0,1))\n\t\t\tif blend>0:\n\t\t\t\tvar from_position: Vector3=actor.position\n\t\t\t\tvar from_rotation: Vector3=actor.rotation\n\t\t\t\tvar sleeping_spot:=Lounge.sleep_spot(spot,id,game.service.progress.lounge_tier)\n\t\t\t\tactor.sleep_pose(sleeping_spot,age,id)\n\t\t\t\tactor.position=from_position.lerp(actor.position,blend)\n\t\t\t\tactor.position.y+=sin(blend*PI)*0.35\n\t\t\t\tvar target_rotation: Vector3=actor.rotation\n\t\t\t\tactor.rotation=Vector3(lerp_angle(from_rotation.x,target_rotation.x,blend),lerp_angle(from_rotation.y,target_rotation.y,blend),lerp_angle(from_rotation.z,target_rotation.z,blend))\n\t\t\t\tactor.caption.text=str(info.name)+" · "+str(sleeping_spot.activity)\n\t\t\t\tactor.caption.visible=false\n\t\t\t\tentry.settled=false\n\t\t\t\tentry.sleepy.visible=blend>0.9\n\t\t\t\tentry.sleepy.position=actor.head.global_position+Vector3(0,0.45+sin(age*1.4+id)*0.08,0)\n\tfor id in performers.keys():\n\t\tif id not in current_ids:\n\t\t\tperformers[id].actor.queue_free(); performers[id].hat.queue_free(); performers[id].sleepy.queue_free(); performers.erase(id)\n\tif wake_scene or cinematic:\n\t\tif is_instance_valid(lounge_ball): lounge_ball.hide()\n\telse:\n\t\t_animate_floor_ball(game.service.progress.night_elapsed)\n'''
i=s.index('func _process(_delta: float) -> void:\n')
s=s[:i]+new_process+'\n'
p.write_text(s)

# --- regression test: unanimous skip enters wake scene, then wake scene ends ---
p = Path('tests/test_cafe_annex.gd')
s = p.read_text()
s = s.replace('const Annex=preload("res://scripts/cafe_annex.gd")\n', 'const Annex=preload("res://scripts/cafe_annex.gd")\nconst Lounge=preload("res://scripts/lounge_layout.gd")\n')
s = s.replace('''\tgame.session.execute_action(7,{"action":"skip_sleep"})\n\tgame.session.advance(0.1)\n\tcheck(game.service.progress.day==day_before+1 and game.service.progress.shift=="open","All connected players sleeping starts next day")\n\tcheck(game.session.sleeping_peers.is_empty(),"Sleep readiness clears after morning")\n\tcheck(game.service.open_for_business,"Morning automatically opens cafe")\n''', '''\tgame.session.execute_action(7,{"action":"skip_sleep"})\n\tgame.session.advance(0.1)\n\tcheck(game.service.progress.day==day_before+1 and game.service.progress.shift=="open","All connected players sleeping starts next day")\n\tcheck(game.session.sleep_scene_active() and game.session.sleep_scene_phase()=="wake","Morning keeps a synchronized wake scene active")\n\tcheck(not game.session.sleeping_peers.is_empty(),"Players remain in the shared bed during the wake shot")\n\tgame.evening._process(0.0)\n\tcheck(game.evening.performers.size()==1,"Worker actor survives into the morning run-back scene")\n\tgame.session.execute_action(1,{"action":"skip_sleep"})\n\tgame.session.execute_action(7,{"action":"skip_sleep"})\n\tgame.session.advance(0.1)\n\tcheck(not game.session.sleep_scene_active() and game.session.sleeping_peers.is_empty(),"Unanimous morning skip completes the cinematic and clears sleepers")\n\tcheck(game.service.open_for_business,"Morning automatically opens cafe")\n\tvar floor_a:=Lounge.overflow_slot(0,2,[])\n\tvar floor_b:=Lounge.overflow_slot(1,2,[])\n\tcheck(absf(float(floor_a.yaw)-float(floor_b.yaw))>0.05,"Floor lounge spots face different directions around social groups")\n''')
p.write_text(s)

